async function loyaltyCards(db,scope,id){
 const column=scope==='customer'?'customer_id':'owner_id';
 const rows=(await db.prepare(`SELECT b.owner_id,b.customer_id, SUM(CASE WHEN b.status='completed' AND r.booking_id IS NULL THEN 1 ELSE 0 END) AS earned, SUM(CASE WHEN r.booking_id IS NOT NULL AND b.status IN('pending','confirmed','completed') THEN 1 ELSE 0 END) AS used, SUM(CASE WHEN r.booking_id IS NOT NULL AND b.status='completed' THEN 1 ELSE 0 END) AS redeemed FROM catalog_live_bookings b LEFT JOIN catalog_loyalty_rewards r ON r.booking_id=b.id WHERE b.${column}=? GROUP BY b.owner_id,b.customer_id`).bind(id).all()).results;
 const settings=(await db.prepare("SELECT l.owner_id,l.service_id,r.name FROM catalog_loyalty_settings l JOIN catalog_services s ON s.id=l.service_id JOIN catalog_revisions r ON r.id=s.published_revision WHERE r.status='approved' AND r.active=1").all()).results;
 return rows.map(r=>{const setting=settings.find(s=>s.owner_id===r.owner_id),remaining=Math.max(0,r.earned-3*r.used);return {salonId:r.owner_id,customerId:r.customer_id,stamps:Math.min(3,Math.max(0,r.earned-3*r.redeemed)),eligible:remaining>=3,serviceId:setting?.service_id||null,serviceName:setting?.name||null}});
}
async function loyaltyBookings(db,rows,scope,id){const cards=await loyaltyCards(db,scope,id);const ratings=(await db.prepare('SELECT booking_id,stars FROM catalog_visit_ratings WHERE '+(scope==='customer'?'customer_id':'owner_id')+'=?').bind(id).all()).results;const rewards=(await db.prepare('SELECT booking_id,discount FROM catalog_loyalty_rewards WHERE '+(scope==='customer'?'customer_id':'owner_id')+'=?').bind(id).all()).results;return {loyalty:cards,bookings:rows.map(r=>({...liveBooking(r),loyalty:cards.find(c=>c.salonId===r.owner_id&&c.customerId===r.customer_id),rating:ratings.find(x=>x.booking_id===r.id)?.stars||null,reward:rewards.some(x=>x.booking_id===r.id)?{...rewards.find(x=>x.booking_id===r.id),status:r.status}:null,reviewRequested:r.status==='completed'}))}}
