  if(actor.role!=='owner')return catalogJson({error:'owner_required'},403);const rows=(await db.prepare('SELECT r.*,m.mime,p.published_revision FROM catalog_products p JOIN catalog_product_revisions r ON r.id=p.latest_revision JOIN catalog_media m ON m.id=r.media_id WHERE p.owner_id=? ORDER BY r.created_at DESC').bind(actor.id).all()).results;return catalogJson({products:rows.map(r=>({...catalogProduct(r,url.origin),publishedRevisionId:r.published_revision}))})
